int ext4_ext_grow_in_inode(handle_t *handle, struct inode *inode, unsigned int flags) {
    struct buffer_head *bh = NULL;
    struct ext4_ext_path *path = NULL;
    struct ext4_extent_header *eh;
    ext4_lblk_t goal;
    int error = 0;

    goal = ext4_ext_get_goal(inode);

    bh = ext4_alloc_block(handle, goal, flags, &error);
    if (!bh) {
        return error;
    }

    path = kmalloc(sizeof(struct ext4_ext_path) * (EXT4_MAX_EXTENT_DEPTH + 1), GFP_NOFS);
    if (!path) {
        brelse(bh);
        return -ENOMEM;
    }

    lock_buffer(bh);
    error = journal_get_write_access(handle, bh);
    if (error) {
        unlock_buffer(bh);
        kfree(path);
        brelse(bh);
        return error;
    }

    error = ext4_ext_move_blocks(inode, bh, path, flags);
    if (error) {
        journal_abort_handle(handle);
        unlock_buffer(bh);
        kfree(path);
        brelse(bh);
        return error;
    }

    eh = ext4_ext_header(bh);
    eh->eh_depth = 0;
    eh->eh_max = EXT4_EXTENT_HEADER_MAX;

    ext4_inode_set(inode, EXT4_I(inode)->i_cached_extent);
    mark_inode_dirty(inode);

    unlock_buffer(bh);
    kfree(path);
    brelse(bh);

    return 0;
}

int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    struct buffer_head *bh = NULL;
    int error = 0;
    struct ext4_ext_header *eh;
    ext4_lblk_t goal;

    goal = ext4_ext_get_depth(inode);
    bh = ext4_alloc_block(handle, goal, flags, &error);
    if (!bh || error)
        return error;

    lock_buffer(bh);
    ext4_journal_get_write_access(handle, bh, flags);
    if (ext4_ext_move_extents(inode, bh, &error) < 0)
        goto out;

    eh = ext4_ext_header(bh);
    eh->eh_magic = cpu_to_le16(EXT4_EXT_MAGIC);
    eh->eh_depth = 0;
    eh->eh_entries = 0;
    eh->eh_max = cpu_to_le16((EXT4_BLOCK_SIZE(inode->i_sb) >> 2) - 2);

    ext4_ext_update_inode(inode, bh, flags);
    ext4_set_inode_flags(inode);
    mark_inode_dirty(inode);

out:
    unlock_buffer(bh);
    brelse(bh);
    return error;
}

int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    int ret = 0;
    struct buffer_head *bh = NULL;
    struct ext4_extent_header *eh;
    struct ext4_extent *ex;
    ext4_lblk_t goal;

    goal = ext4_ext_get_goal(inode);
    bh = ext4_alloc_block(handle, goal, flags, &ret);
    if (!bh)
        return ret;

    lock_buffer(bh);
    ext4_journal_get_write_access(handle, bh, flags);
    if (!ret)
        ret = ext4_ext_move_extents(inode, bh, flags);

    if (!ret) {
        eh = ext4_ext_header(bh);
        ext4_ext_init_header(inode, eh);
        ex = &eh->eh_entries[0];
        ext4_ext_insert(inode, ex, goal);
        inode->i_blocks += 1;
        mark_inode_dirty(inode);
    }

    ext4_journal_put_write_access(handle, bh);
    unlock_buffer(bh);
    brelse(bh);

    return ret;
}

int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags) {
    struct buffer_head *bh = NULL;
    int ret = 0;
    struct ext4_ext_path *path = NULL;
    struct ext4_extent_header *eh;
    ext4_lblk_t goal;

    goal = ext4_ext_find_goal(inode, 0);

    bh = ext4_getblk(NULL, inode, goal, flags);
    if (IS_ERR(bh)) {
        ret = PTR_ERR(bh);
        goto out;
    }

    lock_buffer(bh);
    ret = ext4_journal_get_write_access(handle, bh);
    if (ret < 0)
        goto unlock_out;

    path = kzalloc(sizeof(struct ext4_ext_path) * (EXT4_MAX_EXTENT_DEPTH + 1), GFP_NOFS);
    if (!path) {
        ret = -ENOMEM;
        goto unlock_out;
    }

    ret = ext4_ext_search(inode, path, 0);
    if (ret < 0)
        goto out_free;

    eh = ext4_extent_header(bh);
    eh->eh_magic = cpu_to_le16(EXT4_EXTENT_MAGIC);
    eh->eh_depth = 0;
    eh->eh_entries = 0;
    eh->eh_max = cpu_to_le16((EXT4_BLOCK_SIZE(inode->i_sb) - sizeof(*eh)) / sizeof(struct ext4_extent));

    memcpy(bh->b_data, path->p_extents, path->p_count * sizeof(struct ext4_extent));
    eh->eh_entries = cpu_to_le16(path->p_count);

    unlock_buffer(bh);
    ext4_mark_inode_dirty(handle, inode);
    ext4_free_path(path);

    return 0;

unlock_out:
    unlock_buffer(bh);
out_free:
    kfree(path);
out:
    brelse(bh);
    return ret;
}

int ext4_ext_grow_inodes(handle_t *handle, struct inode *inode, unsigned int flags)
{
    int ret = 0;
    struct buffer_head *bh = NULL;
    struct ext4_ext_header *eh;
    struct ext4_inode_info *ei = EXT4_I(inode);
    ext4_lblk_t goal;

    /* Determine the goal block for the new extent based on depth */
    goal = ext4_ext_get_depth(inode);

    /* Allocate a new block */
    bh = ext4_alloc_block(handle, goal, flags);
    if (!bh) {
        ret = -ENOSPC;
        goto out;
    }

    /* Lock the buffer and prepare for journal access */
    lock_buffer(bh);
    ret = ext4_journal_get_write_access(handle, bh);
    if (ret) {
        unlock_buffer(bh);
        goto out_bh;
    }

    /* Move existing extent data to the new block */
    memcpy(bh->b_data, ei->i_ext.ext, sizeof(ei->i_ext.ext));
    ei->i_ext.ext = bh->b_data;

    /* Initialize the extent header */
    eh = ext4_ext_header(bh);
    eh->eh_magic = cpu_to_le16(EXT4_EXT_MAGIC);
    eh->eh_depth = cpu_to_le16(1);
    eh->eh_entries = cpu_to_le16(EXT4_EXT_INIT_ENTRIES);

    /* Mark the inode as dirty */
    mark_inode_dirty(inode);

    /* Unlock the buffer and release it */
    unlock_buffer(bh);
    brelse(bh);

out:
    return ret;

out_bh:
    brelse(bh);
    goto out;
}
